lemma pow_growth (_hapos : ∀ n, 0 < a n) {M : ℕ}
    (hsq : ∀ m ≥ M, (a m : ℝ) ^ 2 ≤ (a (m + 1) : ℝ)) (k : ℕ) :
    (a M : ℝ) ^ (2 ^ k) ≤ (a (M + k) : ℝ)

lemma tail_b_le_two_tail_a (hapos : ∀ n, 0 < a n) {b : ℕ → ℕ}
    (hsuma : Summable (fun n => 1 / (a n : ℝ)))
    (hsumb : Summable (fun n => 1 / (b n : ℝ))) {N₁ : ℕ}
    (hbge : ∀ n ≥ N₁, (a n : ℝ) / 2 ≤ (b n : ℝ)) (N : ℕ) (hN : N₁ ≤ N + 1) :
    ∑' i, (1 / (b (i + (N + 1)) : ℝ)) ≤ 2 * ∑' i, (1 / (a (i + (N + 1)) : ℝ))

lemma not_tendsto_root_of_cap (hapos : ∀ n, 0 < a n) {N₂ C : ℕ}
    (hcap : ∀ n ≥ N₂, a (n + 1) ≤ C * ∏ i ∈ Finset.range (n + 1), a i) :
    ¬ Tendsto (fun n => (a n : ℝ) ^ (1 / (2 : ℝ) ^ n)) atTop atTop

lemma prod_cap_iter {N₂ C : ℕ}
    (hcap : ∀ n ≥ N₂, a (n + 1) ≤ C * ∏ i ∈ Finset.range (n + 1), a i) (k : ℕ) :
    a (N₂ + 1 + k) ≤ (C * ∏ i ∈ Finset.range (N₂ + 1), a i) ^ (2 ^ k)

lemma ncard_fiber_eq (hapos : ∀ n, 0 < a n) (hf : ∀ X : ℕ, {i : ℕ | a i ≤ X}.Finite)
    (x : ℕ) :
    Set.ncard {m : ℕ | asort a hf m = x} = Set.ncard {i : ℕ | a i = x}
